1	// ============================================================================
2	// tests/hw/pp_stage_binding.cu — JIT binding for the PIPELINE-PARALLEL 2-stage
3	// loopback gate (design §4, task #25 phase-2, Lane C).
4	//
5	// Drives csrc/fused/sm_90/pp_stage_decoder_tc.cuh on ONE GPU: both stages of a
6	// PP=2 split of the decoder TC megakernel run as sequential launches on one
7	// device, sharing one workspace (the acts handoff is zero-copy — exactly the
8	// virtual-boundary discipline ef433ac used for DP=2). The 1F1B mb=1 order:
9	//
10	//     [stage0 fwd]  →  X_in[1] boundary acts (bf16 [T,d], in the shared ws)
11	//     [stage1 fwd+bwd] (the fused last-stage unit) → owned grads {14..29}
12	//                      + loss + dh_boundary (fp32 [T,d])
13	//     [stage0 fwd-recompute+bwd] (dh_in = dh_boundary) → owned grads {0..13}
14	//
15	// The test (test_pp2_loopback_determinism.py) asserts the CONCATENATED grad +
16	// loss are BIT-IDENTICAL to the single-launch production fused step's
17	// (return_grad) output, and A/A/A across 3 reruns — the PP analogue of
18	// ef433ac's DP=2 cross-rank A/A/A.
19	//
20	// REQUIRES the layer-range patch on model_stage_decoder_tc.cuh (the include
21	// chain #errors loudly if absent — see pp_stage_decoder_tc.cuh). JIT-built into
22	// /workspace/.torch_ext; owns its PYBIND11_MODULE (excluded from _ops by
23	// setup.py::_owns_extension_module).
24	// ============================================================================
25	
26	#define SG_TUNED_GEMM_IMPL 1   // the wgmma (production L3-TC) path
27	
28	#include <torch/extension.h>
29	#include <c10/cuda/CUDAStream.h>
30	#include <cuda_runtime.h>
31	#include <cstdint>
32	#include <vector>
33	
34	#include "csrc/fused/sm_90/pp_stage_decoder_tc.cuh"
35	
36	namespace {
37	
38	using namespace sg::fused;          // PersistentContext
39	using namespace sg::fused::sm90;    // dec::, dectc::, DecoderTokenCtx
40	namespace pp = sg::fused::sm90::pp;
41	
42	constexpr int kNumStages = 2;       // the race decoder: 2 layers → 1 layer/stage
43	
44	// One PersistentContext worth of device slots carved from an int32 tensor:
45	// [ g_next_task | g_arrived | g_generation ].
46	PersistentContext make_ctx(at::Tensor& slots) {
47	    PersistentContext ctx{};
48	    int* base = slots.data_ptr<int>();
49	    ctx.g_next_task  = base;
50	    ctx.g_arrived    = reinterpret_cast<unsigned*>(base + 1);
51	    ctx.g_generation = reinterpret_cast<unsigned*>(base + 2);
52	    ctx.n_tasks = kDecNumTensors;   // unused by the PP stages (no P3) — kept uniform
53	    ctx.n_ctas = 0;                 // launcher fills
54	    return ctx;
55	}
56	
57	// ─────────────────────────────────────────────────────────────────────────
58	//  pp2_step — ONE PP=2 loopback step. params [total] fp32 (NOT mutated — the
59	//  optimizer is the separate sharded-opt kernel, design §2.2); tokens [T] /
60	//  targets [B] int32 CUDA. Returns (loss[1], grad[total], dh[T*d]).
61	//  ncta_cap mirrors the production launcher arg (0 = one CTA per SM).
62	// ─────────────────────────────────────────────────────────────────────────
63	std::vector<at::Tensor> pp2_step(at::Tensor params, at::Tensor tokens,
64	                                 at::Tensor targets, int64_t ncta_cap) {
65	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == at::kFloat &&
66	                params.is_contiguous() && params.numel() == kDecTotalElems,
67	                "params must be CUDA fp32 contiguous [", kDecTotalElems, "]");
68	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == at::kInt && tokens.is_contiguous(),
69	                "tokens must be CUDA int32 contiguous [B*kSeq]");
70	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == at::kInt && targets.is_contiguous(),
71	                "targets must be CUDA int32 contiguous [B]");
72	    const int B = (int)targets.numel();
73	    const int T = B * dec::kSeq;
74	    TORCH_CHECK(tokens.numel() == (int64_t)T, "tokens numel != B*kSeq");
75	    TORCH_CHECK(B % 16 == 0, "B must be a multiple of 16 (wgmma K-step), got ", B);
76	
77	    int dev = 0;
78	    TORCH_CHECK(cudaGetDevice(&dev) == cudaSuccess);
79	    int n_sms = 0;
80	    TORCH_CHECK(cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) == cudaSuccess);
81	    unsigned nCTA = (unsigned)n_sms;
82	    if (ncta_cap > 0 && (unsigned)ncta_cap < nCTA) nCTA = (unsigned)ncta_cap;
83	
84	    auto opts_f = params.options();
85	    auto opts_i = tokens.options();
86	    // SAME workspace carve as the production fused step (shared by all three
87	    // launches — the zero-copy acts handoff + identical dw_part slot bases).
88	    const int64_t ws_floats = dec_tc_workspace_floats(T, B, (int)nCTA);
89	    at::Tensor ws    = at::zeros({ws_floats}, opts_f);
90	    at::Tensor grad  = at::zeros({(int64_t)kDecTotalElems}, opts_f);
91	    at::Tensor dh    = at::zeros({(int64_t)T * dec::kD}, opts_f);   // fp32 boundary adjoint
92	    at::Tensor loss  = at::zeros({1}, opts_f);
93	    at::Tensor slots = at::zeros({4}, opts_i);                      // ctx slots
94	
95	    DecoderTokenCtx tok{};
96	    tok.tokens   = tokens.data_ptr<int>();
97	    tok.targets  = targets.data_ptr<int>();
98	    tok.B        = B;
99	    tok.workspace = ws.data_ptr<float>();
100	    tok.loss_out = loss.data_ptr<float>();
101	
102	    PersistentContext ctx = make_ctx(slots);
103	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
104	    const float* p = params.data_ptr<float>();
105	    float* g = grad.data_ptr<float>();
106	    float* dhp = dh.data_ptr<float>();
107	
108	    // [1] stage0 FWD — boundary acts X_in[1] into the shared workspace.
109	    cudaError_t err = pp::launch_pp_decoder_stage_fwd_tc<0, kNumStages>(
110	        ctx, p, tok, stream, (int)ncta_cap);
111	    TORCH_CHECK(err == cudaSuccess, "stage0 fwd launch: ", cudaGetErrorString(err));
112	
113	    // [2] stage1 FWD+BWD (the fused last-stage unit): consumes X_in[1], produces
114	    //     owned grads {14..29} + loss + the fp32 dh boundary handoff.
115	    err = pp::launch_pp_decoder_stage_bwd_tc<1, kNumStages>(
116	        ctx, p, tok, g, /*dh_in=*/nullptr, /*dh_out=*/dhp, stream, (int)ncta_cap);
117	    TORCH_CHECK(err == cudaSuccess, "stage1 bwd launch: ", cudaGetErrorString(err));
118	
119	    // [3] stage0 FWD-RECOMPUTE+BWD: consumes dh, produces owned grads {0..13}.
120	    err = pp::launch_pp_decoder_stage_bwd_tc<0, kNumStages>(
121	        ctx, p, tok, g, /*dh_in=*/dhp, /*dh_out=*/nullptr, stream, (int)ncta_cap);
122	    TORCH_CHECK(err == cudaSuccess, "stage0 bwd launch: ", cudaGetErrorString(err));
123	
124	    return {loss, grad, dh};
125	}
126	
127	// Host-side ownership introspection (the Python pipeline plan cross-checks
128	// against THIS — the kernel-side single source).
129	std::vector<int64_t> pp2_owned_tensors(int64_t stage) {
130	    std::vector<int64_t> out;
131	    for (int t = 0; t < kDecNumTensors; ++t) {
132	        const bool own = (stage == 0)
133	            ? pp::PPStageSpec<0, kNumStages>::owns_tensor(t)
134	            : pp::PPStageSpec<1, kNumStages>::owns_tensor(t);
135	        if (own) out.push_back(t);
136	    }
137	    return out;
138	}
139	
140	// Per-tensor (offset, size) of the dec layout — lets the test slice the grad
141	// per owned tensor without re-deriving the layout in Python.
142	std::vector<int64_t> pp2_layout() {
143	    std::vector<int64_t> out;
144	    for (int t = 0; t < kDecNumTensors; ++t) {
145	        out.push_back(sm90::dec_layout_check::kOffsets[t]);
146	        out.push_back(sm90::dec_layout_check::kSizes[t]);
147	    }
148	    return out;
149	}
150	
151	}  // namespace
152	
153	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
154	    m.doc() = "PP=2 loopback stage binding (design §4; layer-range patch required).";
155	    m.def("pp2_step", &pp2_step,
156	          "Run one PP=2 loopback step (s0 fwd → s1 fwd+bwd → s0 fwd+bwd); "
157	          "returns (loss[1], grad[total], dh_boundary[T*d]).",
158	          py::arg("params"), py::arg("tokens"), py::arg("targets"),
159	          py::arg("ncta_cap") = 0);
160	    m.def("pp2_owned_tensors", &pp2_owned_tensors,
161	          "Tensor indices owned by a stage (kernel-side single source).");
162	    m.def("pp2_layout", &pp2_layout, "Flat [off,size]*30 of the decoder layout.");
163	    m.attr("TOTAL") = (int64_t)kDecTotalElems;
164	    m.attr("SEQ") = (int64_t)dec::kSeq;
165	    m.attr("NUM_STAGES") = (int64_t)kNumStages;
166	}
