322	// ─────────────────────────────────────────────────────────────────────────
323	//  Host plumbing.
324	// ─────────────────────────────────────────────────────────────────────────
325	#define CHK(t, n, len) \
326	    TORCH_CHECK((t).is_cuda() && (t).scalar_type() == at::kFloat && (t).is_contiguous() \
327	                && (t).numel() == (len), n " must be CUDA fp32 contiguous of numel ", (int64_t)(len))
328	
329	void tp_loopback_run(int64_t P_,
330	                     at::Tensor X, at::Tensor dY1,
331	                     at::Tensor W0s, at::Tensor b0s, at::Tensor W1s, at::Tensor b1,
332	                     at::Tensor Y1, at::Tensor dX,
333	                     at::Tensor dW0, at::Tensor db0, at::Tensor dW1, at::Tensor db1) {
334	    const int P = (int)P_;
335	    TORCH_CHECK(P >= 2 && kDff % P == 0 && (kDff / P) % 16 == 0,
336	                "TP degree must divide dff with 16 | dff/P (wgmma K-step); got P=", P);
337	    const int F = kDff / P;
338	    CHK(X, "X", (int64_t)kM * kD); CHK(dY1, "dY1", (int64_t)kM * kD);
339	    CHK(W0s, "W0s", (int64_t)kDff * kD); CHK(b0s, "b0s", (int64_t)kDff);
340	    CHK(W1s, "W1s", (int64_t)kD * kDff); CHK(b1, "b1", (int64_t)kD);
341	    CHK(Y1, "Y1", (int64_t)P * kM * kD); CHK(dX, "dX", (int64_t)P * kM * kD);
342	    CHK(dW0, "dW0", (int64_t)kDff * kD); CHK(db0, "db0", (int64_t)kDff);
343	    CHK(dW1, "dW1", (int64_t)kD * kDff); CHK(db1, "db1", (int64_t)P * kD);
344	
345	    auto opts_f = X.options();
346	    auto opts_b = X.options().dtype(at::kBFloat16);
347	    // bf16 inputs (round once host-side via torch, exact production round).
348	    at::Tensor Xb  = X.to(at::kBFloat16).contiguous();
349	    at::Tensor dYb = dY1.to(at::kBFloat16).contiguous();
350	    // Scratch + the loopback symmetric heap (zero-init: determinism of the heap
351	    // content before first publish; the publish overwrites every read element).
352	    at::Tensor heap = at::zeros({(int64_t)P * 2 * kM * kD}, opts_f);
353	    at::Tensor pre  = at::zeros({(int64_t)P * kM * F}, opts_b);
354	    at::Tensor G    = at::zeros({(int64_t)P * kM * F}, opts_b);
355	    at::Tensor dG   = at::zeros({(int64_t)P * kM * F}, opts_f);
356	    at::Tensor dY0  = at::zeros({(int64_t)P * kM * F}, opts_b);
357	    at::Tensor barb = at::zeros({2}, X.options().dtype(at::kInt));  // arrived|generation
358	
359	    TpArgs a{};
360	    a.X   = reinterpret_cast<const __nv_bfloat16*>(Xb.data_ptr());
361	    a.dY1 = reinterpret_cast<const __nv_bfloat16*>(dYb.data_ptr());
362	    a.W0s = W0s.data_ptr<float>(); a.b0s = b0s.data_ptr<float>();
363	    a.W1s = W1s.data_ptr<float>(); a.b1 = b1.data_ptr<float>();
364	    a.heap = heap.data_ptr<float>();
365	    a.pre = reinterpret_cast<__nv_bfloat16*>(pre.data_ptr());
366	    a.G   = reinterpret_cast<__nv_bfloat16*>(G.data_ptr());
367	    a.dG  = dG.data_ptr<float>();
368	    a.dY0 = reinterpret_cast<__nv_bfloat16*>(dY0.data_ptr());
369	    a.Y1 = Y1.data_ptr<float>(); a.dX = dX.data_ptr<float>();
370	    a.dW0 = dW0.data_ptr<float>(); a.db0 = db0.data_ptr<float>();
371	    a.dW1 = dW1.data_ptr<float>(); a.db1 = db1.data_ptr<float>();
372	    a.P = P;
373	
374	    unsigned* barp = reinterpret_cast<unsigned*>(barb.data_ptr<int>());
375	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
376	    tp_loopback_block_kernel<<<P, kBlk, 0, stream>>>(a, barp, barp + 1);
377	    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "tp_loopback_block_kernel launch failed");
378	}
