380	void tp_reference_run(int64_t P_,
381	                      at::Tensor X, at::Tensor dY1,
382	                      at::Tensor W0, at::Tensor b0, at::Tensor W1, at::Tensor b1,
383	                      at::Tensor W0s, at::Tensor b0s, at::Tensor W1s,
384	                      at::Tensor Y1_ref, at::Tensor dX_ref,
385	                      at::Tensor dW0_ref, at::Tensor db0_ref,
386	                      at::Tensor dW1_ref, at::Tensor db1_ref,
387	                      at::Tensor Y1_chunked, at::Tensor dX_chunked) {
388	    const int P = (int)P_;
389	    const int F = kDff / P;
390	    CHK(X, "X", (int64_t)kM * kD); CHK(dY1, "dY1", (int64_t)kM * kD);
391	    CHK(W0, "W0", (int64_t)kDff * kD); CHK(b0, "b0", (int64_t)kDff);
392	    CHK(W1, "W1", (int64_t)kD * kDff); CHK(b1, "b1", (int64_t)kD);
393	    CHK(W0s, "W0s", (int64_t)kDff * kD); CHK(b0s, "b0s", (int64_t)kDff);
394	    CHK(W1s, "W1s", (int64_t)kD * kDff);
395	    CHK(Y1_ref, "Y1_ref", (int64_t)kM * kD); CHK(dX_ref, "dX_ref", (int64_t)kM * kD);
396	    CHK(dW0_ref, "dW0_ref", (int64_t)kDff * kD); CHK(db0_ref, "db0_ref", (int64_t)kDff);
397	    CHK(dW1_ref, "dW1_ref", (int64_t)kD * kDff); CHK(db1_ref, "db1_ref", (int64_t)kD);
398	    CHK(Y1_chunked, "Y1_chunked", (int64_t)kM * kD); CHK(dX_chunked, "dX_chunked", (int64_t)kM * kD);
399	
400	    auto opts_f = X.options();
401	    auto opts_b = X.options().dtype(at::kBFloat16);
402	    at::Tensor Xb  = X.to(at::kBFloat16).contiguous();
403	    at::Tensor dYb = dY1.to(at::kBFloat16).contiguous();
404	    at::Tensor pre_full = at::zeros({(int64_t)kM * kDff}, opts_b);
405	    at::Tensor G_full   = at::zeros({(int64_t)kM * kDff}, opts_b);
406	    at::Tensor dY0_full = at::zeros({(int64_t)kM * kDff}, opts_b);
407	    at::Tensor scratch  = at::zeros({(int64_t)kM * kDff}, opts_f);
408	    at::Tensor pre_o    = at::zeros({(int64_t)kM * F}, opts_b);
409	    at::Tensor G_o      = at::zeros({(int64_t)kM * F}, opts_b);
410	    at::Tensor dY0_o    = at::zeros({(int64_t)kM * F}, opts_b);
411	    at::Tensor part     = at::zeros({(int64_t)kM * kD}, opts_f);
412	
413	    TpRefArgs a{};
414	    a.X = reinterpret_cast<const __nv_bfloat16*>(Xb.data_ptr());
415	    a.dY1 = reinterpret_cast<const __nv_bfloat16*>(dYb.data_ptr());
416	    a.W0 = W0.data_ptr<float>(); a.b0 = b0.data_ptr<float>();
417	    a.W1 = W1.data_ptr<float>(); a.b1 = b1.data_ptr<float>();
418	    a.W0s = W0s.data_ptr<float>(); a.b0s = b0s.data_ptr<float>();
419	    a.W1s = W1s.data_ptr<float>();
420	    a.pre_full = reinterpret_cast<__nv_bfloat16*>(pre_full.data_ptr());
421	    a.G_full   = reinterpret_cast<__nv_bfloat16*>(G_full.data_ptr());
422	    a.dY0_full = reinterpret_cast<__nv_bfloat16*>(dY0_full.data_ptr());
423	    a.scratch_f = scratch.data_ptr<float>();
424	    a.pre_o = reinterpret_cast<__nv_bfloat16*>(pre_o.data_ptr());
425	    a.G_o   = reinterpret_cast<__nv_bfloat16*>(G_o.data_ptr());
426	    a.dY0_o = reinterpret_cast<__nv_bfloat16*>(dY0_o.data_ptr());
427	    a.part = part.data_ptr<float>();
428	    a.Y1_ref = Y1_ref.data_ptr<float>(); a.dX_ref = dX_ref.data_ptr<float>();
429	    a.dW0_ref = dW0_ref.data_ptr<float>(); a.db0_ref = db0_ref.data_ptr<float>();
430	    a.dW1_ref = dW1_ref.data_ptr<float>(); a.db1_ref = db1_ref.data_ptr<float>();
431	    a.Y1_chunked = Y1_chunked.data_ptr<float>(); a.dX_chunked = dX_chunked.data_ptr<float>();
432	    a.P = P;
433	
434	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
435	    tp_reference_kernel<<<1, kBlk, 0, stream>>>(a);
436	    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "tp_reference_kernel launch failed");
437	}
