480	          "Run the TP=P virtual-rank col→row pair fwd+bwd over the loopback "
481	          "symmetric heap (fixed-order all-reduce at the two comm points).");
482	    m.def("tp_reference_run", &tp_reference_run,
483	          "Run the 1-CTA unsharded + serial-chunked-order references.");
484	    m.def("tp_pack_pair_shards", &tp_pack_pair_shards,
485	          "Pack dense per-rank (W0 col / W1 row) shards via the tp_layer maps.");
486	    m.attr("M") = kM; m.attr("D") = kD; m.attr("DFF") = kDff;
487	}
