46	static int eff_nctas(const torch::Tensor& params, int cap) {
47	    int dev = params.get_device();
48	    int n = ::sg::fused::sm90::mb_tc_launched_nctas<OptId::Prodigy>(dev, cap);
49	    if (n <= 0) {
50	        int n_sms = 1;
51	        cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
52	        n = n_sms;
53	        if (cap > 0 && cap < n) n = cap;
54	    }
55	    return n;
56	}
