58	static TcScratch g_scratch_singleton;
59	TcScratch& _last_scratch() { return g_scratch_singleton; }
60	static TcScratch& scratch_for(const torch::Tensor& params, int B, int nCTA) {
61	    TcScratch& s = g_scratch_singleton;
62	    const int T = B * mb::kSeq;
63	    const int64_t need = ::sg::fused::sm90::mb_tc_workspace_floats(T, nCTA);
64	    if (!s.g_next.defined()) {
65	        auto oi = torch::dtype(torch::kInt32).device(params.device());
66	        s.g_next = torch::zeros({1}, oi);
67	        s.g_arrived = torch::zeros({1}, oi);
68	        s.g_generation = torch::zeros({1}, oi);
69	    }
70	    if (s.ws_floats < need) {
71	        auto of = torch::dtype(torch::kFloat32).device(params.device());
72	        s.workspace = torch::empty({need}, of);
73	        s.ws_floats = need;
74	    }
75	    // DIAGNOSTIC sentinel fill (read-before-write probe). Region mode ALWAYS zeroes
76	    // the whole workspace first, then sets [a,b) to the sentinel — so a clean (0)
77	    // baseline isolates exactly the region under test (no cached-residue contamination).
78	    if (g_ws_fill_on) {
79	        if (g_ws_fill_a < 0) {
80	            s.workspace.fill_(g_ws_fill);
81	        } else {
82	            s.workspace.fill_(0.0f);
83	            s.workspace.slice(0, g_ws_fill_a, std::min<int64_t>(g_ws_fill_b, s.ws_floats)).fill_(g_ws_fill);
84	        }
85	    }
86	    return s;
87	}
