93	// One mamba TC step under OptId::Prodigy. state layout: a flat fp32 buffer holding
94	// [m | v | extra] with extra big enough; param_init is a separate [total] tensor
95	// seeded == params at step 1; prodigy_persist a [3] device scalar buffer.
96	// Returns {loss(cpu), grad[total], params_after(clone)}.
97	static std::vector<torch::Tensor> prodigy_step(
98	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
99	        torch::Tensor state, torch::Tensor param_init, torch::Tensor persist,
100	        double lr, double beta1, double beta2, double eps, double weight_decay,
101	        double bc1, double bc2, double d0, double d_coef, double beta3,
102	        int64_t step, int64_t ncta_cap) {
103	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
104	    TORCH_CHECK(params.numel() == kMambaTotalElems);
105	    const int B = (int)targets.numel();
106	    TORCH_CHECK((B % 16) == 0);
107	    const int64_t total = kMambaTotalElems;
108	
109	    const int nCTA = eff_nctas(params, (int)ncta_cap);
110	    TcScratch& sc = scratch_for(params, B, nCTA);
111	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
112	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
113	
114	    PersistentContext ctx{
115	        sc.g_next.data_ptr<int>(),
116	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
117	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
118	        kMambaNumTensors, 0u};
119	
120	    FusedOptState st;
121	    float* m = state.data_ptr<float>();
122	    st.exp_avg = m;
123	    st.exp_avg_sq = m + total;
124	    st.s_track = m + 2 * total;   // Prodigy `s` per-element accumulator (extra slice)
125	    st.ema     = m + 2 * total;   // alias (harmless; prodigy has no slow-grad EMA)
126	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
127	    st.eps = (float)eps; st.wd = (float)weight_decay;
128	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
129	    st.param_init = param_init.data_ptr<float>();
130	    st.prodigy_persist = persist.data_ptr<float>();
131	    st.d0 = (float)d0; st.d_coef = (float)d_coef; st.beta3 = (float)beta3;
132	
133	    MambaTokenCtx tok;
134	    tok.tokens = tokens.data_ptr<int>();
135	    tok.targets = targets.data_ptr<int>();
136	    tok.B = B;
137	    tok.workspace = sc.workspace.data_ptr<float>();
138	    tok.loss_out = loss_dev.data_ptr<float>();
139	
140	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
141	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel_tc<OptId::Prodigy>(
142	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
143	        (float)lr, (int)step, st, stream, nCTA);
144	    TORCH_CHECK(err == cudaSuccess, "prodigy TC launch failed: ", cudaGetErrorString(err));
145	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
146	    return {loss_dev.to(torch::kCPU), grad, params.clone()};
147	}
