158	    TORCH_CHECK(params.numel() == kMambaTotalElems);
159	    const int B = (int)targets.numel();
160	    TORCH_CHECK((B % 16) == 0);
161	    const int64_t total = kMambaTotalElems;
162	
163	    const int nCTA = eff_nctas(params, (int)ncta_cap);
164	    TcScratch& sc = scratch_for(params, B, nCTA);
165	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
166	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
167	
168	    PersistentContext ctx{
169	        sc.g_next.data_ptr<int>(),
170	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
171	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
172	        kMambaNumTensors, 0u};
173	
174	    FusedOptState st;
175	    float* m = state.data_ptr<float>();
176	    st.exp_avg = m;
177	    st.exp_avg_sq = m + total;
178	    st.sam_dir = m + 2 * total;   // persistent cached SAM direction (extra slice)
179	    st.ema     = m + 2 * total;   // alias (harmless)
180	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
