184	
185	    MambaTokenCtx tok;
186	    tok.tokens = tokens.data_ptr<int>();
187	    tok.targets = targets.data_ptr<int>();
188	    tok.B = B;
189	    tok.workspace = sc.workspace.data_ptr<float>();
190	    tok.loss_out = loss_dev.data_ptr<float>();
191	
192	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
193	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel_tc<OptId::LookSAM>(
194	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
195	        (float)lr, (int)step, st, stream, nCTA);
196	    TORCH_CHECK(err == cudaSuccess, "looksam TC launch failed: ", cudaGetErrorString(err));
197	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
198	    return {loss_dev.to(torch::kCPU), grad, state.slice(0, 2 * total, 3 * total).clone()};
199	}
