201	// DIAG: clone the cached workspace (acts + scratch + partials) after the last
202	// launch, so Python can diff the FORWARD acts vs BACKWARD acts across runs to
203	// localize where the non-determinism first appears.
204	static torch::Tensor dump_ws(int64_t B, int64_t ncta_cap) {
205	    static TcScratch* last = nullptr;
206	    (void)B; (void)ncta_cap;
207	    // scratch_for keeps a single static instance; re-fetch it via a dummy params on CUDA.
208	    extern TcScratch& _last_scratch();
209	    TcScratch& sc = _last_scratch();
210	    if (!sc.workspace.defined()) return torch::zeros({1});
211	    return sc.workspace.clone();
212	}
