1	// tests/hw/_mb3_scalar_probe.cu — MINIMAL standalone Milestone-A.1/B.1 probe for
2	// the Mamba-3 SCALAR fwd+bwd (model_stage_mamba3.cuh). NOT production: a single
3	// CTA loops all B samples, runs mb_forward_sample + mb_backward_sample, and
4	// accumulates grads with atomicAdd into a flat fp32 grad buffer. This isolates
5	// the Mamba-3 scan/RMSNorm/BCNorm/SwiGLU/block math (fp32) for comparison vs the
6	// fp64 oracle WITHOUT needing the TC rewrite or the persistent megakernel. JIT-
7	// loaded by tests/hw/test_mb3_scalar.py. (Determinism is irrelevant here — this
8	// is a correctness probe; the production path's deterministic reduce is separate.)
9	#include <torch/extension.h>
10	#include <cuda_runtime.h>
11	#include "csrc/fused/sm_90/model_stage_mamba3.cuh"
12	
13	namespace {
14	using namespace sg::fused::sm90;
15	
16	// One CTA, 256 threads. Loops the B samples; per sample runs fwd then bwd,
17	// atomicAdd-ing the per-sample grads into `grad` (flat, kMambaTotalElems). The
18	// loss is summed (fp64-ish via atomicAdd fp32) into loss_out[0]; CE mean over B
19	// is applied by passing B to mb_backward_sample (the dlogits/B) and dividing the
20	// loss sum by B on the host.
21	__global__ void __launch_bounds__(256)
22	mb3_scalar_fwdbwd(const float* __restrict__ params,
23	                  const int* __restrict__ tokens,   // [B, kSeq]
24	                  const int* __restrict__ targets,  // [B]
25	                  int B, float* __restrict__ grad, float* __restrict__ loss_out,
26	                  float* __restrict__ dbg) {
27	    extern __shared__ char smem_raw[];
28	    MambaSampleSmem* sm = reinterpret_cast<MambaSampleSmem*>(smem_raw);
29	    MambaWeights w = mb_bind(params);
30	    MambaGrad g = mb_bind_grad(grad);
31	    for (int s = 0; s < B; ++s) {
32	        const int* tok_s = tokens + (int64_t)s * mb::kSeq;
33	        int tgt = targets[s];
34	        float nll = mb_forward_sample(w, tok_s, tgt, sm);
35	        // DEBUG (sample 0 only): dump block-0 out, final_in, logits, then block-0
36	        // y_scan + x_in (mixer internals) appended after.
37	        if (s == 0 && dbg != nullptr) {
38	            for (int i = threadIdx.x; i < mb::kSeq * mb::kD; i += blockDim.x) {
39	                dbg[i] = sm->layer_in[1][i / mb::kD][i % mb::kD];                 // block-0 out
40	                dbg[mb::kSeq * mb::kD + i] = sm->final_in[i / mb::kD][i % mb::kD]; // block-1 out
41	            }
42	            for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x)
43	                dbg[2 * mb::kSeq * mb::kD + o] = sm->logits[o];                    // logits
44	            const int base = 2 * mb::kSeq * mb::kD + mb::kPHead;
45	            for (int i = threadIdx.x; i < mb::kSeq * mb::kDInner; i += blockDim.x) {
46	                dbg[base + i] = sm->act[0].y_scan[i / mb::kDInner][i % mb::kDInner];
47	                dbg[base + mb::kSeq * mb::kDInner + i] = sm->act[0].x_in[i / mb::kDInner][i % mb::kDInner];
48	            }
49	            __syncthreads();
50	        }
51	        if (threadIdx.x == 0) atomicAdd(loss_out, nll);
52	        mb_backward_sample(w, g, tok_s, tgt, B, sm);
53	    }
54	}
55	
56	std::vector<torch::Tensor> scalar_fwdbwd(torch::Tensor params,
57	                                         torch::Tensor tokens,
58	                                         torch::Tensor targets) {
59	    TORCH_CHECK(params.is_cuda() && params.dtype() == torch::kFloat32, "params fp32 cuda");
60	    const int B = (int)tokens.size(0);
61	    auto grad = torch::zeros_like(params);
62	    auto loss = torch::zeros({1}, params.options());
63	    namespace mbn = sg::fused::sm90::mb;
64	    const int dbg_n = 2 * mbn::kSeq * mbn::kD + mbn::kPHead
65	                      + 2 * mbn::kSeq * mbn::kDInner;
66	    auto dbg = torch::zeros({dbg_n}, params.options());
67	    auto tok32 = tokens.to(torch::kInt32).contiguous();
68	    auto tgt32 = targets.to(torch::kInt32).contiguous();
69	    int64_t smem = kMambaSmemBytes;
70	    cudaFuncSetAttribute(mb3_scalar_fwdbwd, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
71	    mb3_scalar_fwdbwd<<<1, 256, smem>>>(
72	        params.data_ptr<float>(), tok32.data_ptr<int>(), tgt32.data_ptr<int>(),
73	        B, grad.data_ptr<float>(), loss.data_ptr<float>(), dbg.data_ptr<float>());
74	    cudaError_t e = cudaGetLastError();
75	    TORCH_CHECK(e == cudaSuccess, "kernel launch: ", cudaGetErrorString(e));
76	    cudaDeviceSynchronize();
77	    e = cudaGetLastError();
78	    TORCH_CHECK(e == cudaSuccess, "kernel sync: ", cudaGetErrorString(e));
79	    return {loss / (double)B, grad, dbg};
80	}
81	}  // namespace
