83	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
84	    m.def("scalar_fwdbwd", &scalar_fwdbwd, "Mamba-3 scalar fwd+bwd probe");
85	    m.attr("TOTAL") = (int64_t)sg::fused::sm90::kMambaTotalElems;
86	}
